window.LOR_VERIFY = {"cv": "698_2", "checked": "22.10.2026", "pdf": "698_2_Хронический средний отит.pdf", "pages": 55, "items": {"m652": {"s": "ok", "sec": "1.4", "page": 10, "q": "65.2 - Хронический серозный средний отит"}, "m653": {"s": "ok", "sec": "1.4", "page": 10, "q": "65.3 - Хронический слизистый средний отит"}, "m654": {"s": "ok", "sec": "1.4", "page": 10, "q": "65.4 - Другой хронический негнойный средний отит:  аллергический;  экссудативный;  негнойный БДУ;  серозно-муцинозный;  с выпотом (негнойный)"}, "m661": {"s": "ok", "sec": "1.4", "page": 10, "q": "66.1 - Хронический туботимпанальный гнойный средний отит (хроническая туботимпанальная болезнь, мезотимпанит)"}, "m662": {"s": "ok", "sec": "1.4", "page": 10, "q": "66.2 - Хронический эпитимпано-антральный гнойный средний отит (хроническая эпитимпано-антральная болезнь, эпитимпанит)"}, "m663": {"s": "ok", "sec": "1.4", "page": 10, "q": "66.3 - Другой хронический гнойный средний отит"}, "m720": {"s": "ok", "sec": "1.4", "page": 10, "q": "72.0 - Центральная перфорация барабанной перепонки"}, "m900": {"s": "ok", "sec": "1.4", "page": 10, "q": "90.0 - Кондуктивная потеря слуха", "note": "В PDF в слове «двусторонняя» одна буква латинская."}, "m901": {"s": "ok", "sec": "1.4", "page": 10, "q": "90.1 - Кондуктивная потеря слуха односторонняя с нормальным слухом на противоположном ухе"}, "m902": {"s": "ok", "sec": "1.4", "page": 10, "q": "90.2 - Кондуктивная потеря слуха неуточненная"}, "m906": {"s": "ok", "sec": "1.4", "page": 10, "q": "90.6 - Смешанная кондуктивная и нейросенсорная потеря слуха двусторонняя"}, "m907": {"s": "ok", "sec": "1.4", "page": 10, "q": "90.7 - Смешанная кондуктивная и нейросенсорная потеря слуха односторонняя с нормальным слухом на противоположном ухе"}, "m908": {"s": "ok", "sec": "1.4", "page": 10, "q": "90.8 - Смешанная кондуктивная и нейросенсорная потеря слуха неуточненная"}, "s1": {"s": "ok", "sec": "3.2", "page": 25, "q": "Основной вид лечения пациентов с ХГСО – хирургический, который проводится с учетом патогенеза и особенностей клинической картины. Только с помощью оперативного пособия возможно не только полностью санировать больное ухо, но и улучшить качество жизни пациента. Поэтому на современном этапе любой пациент, страдающий ХГСО, является потенциальным кандидатом на оперативное лечение [49, 82]. Операции при ХГСО необходимо проводить в период ремиссии заболевания (не ранее чем через 3-6 месяцев после последнего обострения) для уменьшения объема операции, лучшей дифференцировке жизнеспособных элементов среднего уха, для снижения частоты осложнений и повышения ее эффективности"}, "s2": {"s": "ok", "sec": "2.4", "page": 19, "q": "Рекомендуется выполнять тональную пороговую аудиометрию (ТПА) при диагностике ХГСО [2,30,45,49, 57, 77, 83,88]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 4) Комментарии: аудиологическое обследование пациентов с ХГСО позволяет определить вид тугоухости и прогнозировать функциональный результат операции. ТПА точно определяет степень и характер тугоухости (кондуктивная, смешанная и нейросенсорная) и возможности ее реабилитации. Несмотря на то, что данное исследование является субъективным, оно позволяет прогнозировать результат операции, контролировать его динамику в отдаленном послеоперационном периоде. Так у пациентов с порогами КП выше 30 дБ в диапазоне разговорных частот даже при идеально проведенной хирургической операции качественного улучшения слуха нельзя ожидать"}, "s3": {"s": "ok", "sec": "2.4", "page": 22, "q": "Рекомендуется проведение МРТ височных костей (костной ткани, одна область) пациентам с ХГСО с подозрением на холестеатому или ее рецидив [7, 9, 95, 96, 103, 104]. Уровень убедительности рекомендаций А (уровень достоверности доказательств – 2) Комментарии: МРТ в определенных режимах (T1, T2, EPI DWI, non-EPI DWI) является методом достоверной диагностики холестеатомы и ее рецидива после операции. Метод обладает чувствительностью для холестеатомы в 77-100%, специфичностью – в 86-100% случаев и позволяет отличить ее от других мягкотканных образований височной кости: секрета, грануляций и холестероловой гранулемы"}, "s4": {"s": "ok", "sec": "3.1", "page": 24, "q": "Ключевая роль все же принадлежит антисептикам и дезинфицирующим средствам (D08A), топическим антибактериальным препаратам (S02AA Противомикробные препарат), D01AE (Другие противогрибковые препараты для местного применения) противогрибковым препаратам для местного применения и глюкокортикостероидам (S02CA Кортикостероиды в комбинации с противомикробными средствами). Топические фторхинолоны являются наиболее эффективными средствами лечения ХГСО с минимальными побочными эффектами: они воздействуют на основную патогенную флору (75,6% изолятов чувствительны к данной группе препаратов) и не являются ототоксичными, поэтому можно использовать у пациентов с перфорацией барабанной перепонки. Местное лечение эффективно только после тщательного удаления патологического содержимого из среднего уха с помощью аспирации или ирригации"}, "s5": {"s": "ok", "sec": "5", "page": 33, "q": "Рекомендуется наблюдение пациентов с ХГСО, которым противопоказано проведение хирургического лечения, либо по каким-то причинам оно отсрочено, а также пациентов, отказывающихся от хирургического вмешательства. Данная категория пациентов должна наблюдаться квалифицированным специалистом амбулаторно-поликлинического звена с частотой 1 раз в 6 месяцев и при обострении ХГСО получать консервативное лечение для купирования местного воспаления [152]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5)  Рекомендуется после тимпанопластики и санирующих операций наблюдение с частотой посещения 1 раз в год врачом амбулаторно-поликлинического звена и отохирургом учреждения, где была проведена операция минимум до 5 лет с момента операции. Цель наблюдения – выявление рецидивов перфорации, холестеатомы и тугоухости"}, "c-def": {"s": "ok", "sec": "1.1", "page": 6, "q": "Хронический гнойный средний отит (ХГСО) – хроническое воспаление полостей среднего уха, характеризующееся наличием стойкой перфорации барабанной перепонки, постоянным или периодически возникающим гноетечением из уха и прогрессирующим снижением слуха более 3 месяцев"}, "c-terms": {"s": "ok", "sec": "Термины и определения", "page": 5, "q": "Мукозит – хроническое катаральное воспаление слизистой оболочки среднего уха. Тимпаносклероз–является необратимым исходом неспецифического воспаления среднего уха, характеризующегося тугоухостью, обусловленной фиксацией элементов звукопроводящей цепи за счет мукопериостита барабанной полости со склонностью к гиалинозу и дистрофическому обызвествлению. Тимпанофиброз (фиброзирующий средний отит, фиброзная облитерация барабанной полости) –незаконченный патологический процесс с преобладанием текущего фиброзирования над воспалительными изменениями в барабанной полости. Холестеатома –эпидермальное образование белесовато-перламутрового цвета, обычно имеющее соединительнотканную оболочку (матрикс), которая покрыта многослойным плоским эпителием, плотно прилежит к кости и нередко врастает в нее"}, "c-etio": {"s": "ok", "sec": "1.2", "page": 6, "q": "Причинами развития ХГСО у взрослых является хроническая патология верхних дыхательных путей (полости носа, околоносовых пазух и носоглотки), перенесенные ранее эпизоды ОСО, системная и специфическая патология [1, 2, 3]. Инициирующим звеном в развитии ХГСО являются перенесенный ОСО с формированием стойкой перфорации барабанной перепонки или ретракционных изменений с атрофичной неомембраной, травматическая или ятрогенная перфорация, сохраняющаяся у 1,3-10,8% пациентов после врачебных манипуляций"}, "c-risk": {"s": "ok", "sec": "1.2", "page": 6, "q": "Факторы риска хронизации процесса характерны для ХГСО: анатомические особенности строения среднего уха и слуховой трубы; неадекватная антибактериальная терапия ОСО без дренирования среднего уха; вирулентные штаммы возбудителей, устойчивые к антибактериальным препаратам; ретракционные изменения в барабанной полости после ОСО; увеличение случаев ЭСО, как в детской, так и во взрослой практике; нарушение механизмов местной иммунной защиты с тенденцией к увеличению числа ОРВИ в популяции; хроническая патология носоглотки и полости носа, ведущая к нарушению мукоцилиарного клиренса слизистой оболочки слуховой трубы и, как следствие, к стойкому отрицательному давлению и латентному течению процесса в среднем ухе с тенденцией перехода его в секреторную и фиброзирующую формы"}, "c-flora": {"s": "ok", "sec": "1.2", "page": 7, "q": "Основным микроорганизмом среди аэробов является Pseudomonas aeruginosa, высеваемая изолированно в 31,1-98%, вторым по значимости является Staphylococcus aureus, высеваемый в 15-30% случаев. Из других микроорганизмов встречаются Staphylococcus epidermidis, Streptococcu spyogenes, Klebsiella pneumoniae, Ptoteus mirabilis. Во многих случаях обнаруживается коагулазонегативный стафилококк. Среди анаэробов чаще высеиваются анаэробные грамм-положительные кокки (Peptococcus и Peptostreptococcus в 17,2%), реже Bacteroides (в 12,4%); грамм-отрицательные Klebsiella и Proteus выделяются в 10-20% случаев. Анаэробы чаще сопутствуют холестеатомному процессу, так как внутри ее матрикса условия для их существования более благоприятны. Изоляты, встречающиеся как монокультура, чаще приводят к развитию тяжелых  осложнений ХГСО (мастоидит, внутричерепные осложнения). От 1,4 до 20% случаев приходится на грибковую флору, чаще рода Aspergillus и Candida spp."}, "c-class-icd": {"s": "ok", "sec": "1.5", "page": 10, "q": "По клиническому течению и тяжести заболевания согласно Международной классификации болезней (МКБ-10) принято различать две формы ХГСО:   мезотимпанит (туботимпанальный гнойный средний отит);  эпитимпанит (хронический эпитимпано-антральный гнойный средний отит). Принципиальное различие этих форм состоит в том, что при мезотимпаните в основном поражается слизистая оболочка мезо- и гипотимпанума барабанной полости, а при эпитимпаните – процесс из эпитимпанума распространяется в клетки сосцевидного отростка с поражением костных структур среднего уха"}, "c-class-morph": {"s": "ok", "sec": "1.5", "page": 11, "q": "На основе клинико-морфологических исследований предложена классификация ХСО, где выделяются [6]:  неперфоративная форма: • экссудативный, • адгезивный (рубцовый), • с тимпаносклерозом, • с тимпанофиброзом.  перфоративная форма: • сухой средний отит, • с мукозитом, • с тимпаносклерозом, • с холестеатомой"}, "c-class-loc": {"s": "ok", "sec": "1.5", "page": 11, "q": "Место расположения дефекта барабанной перепонки при ХГСО отражает только преимущественную локализацию воспалительного процесса и не характеризует полиморфизм изменений в среднем ухе, что затрудняет четкое разграничение клинических форм заболевания (доброкачественный или нет) [6, 59, 60, 61, 62]. Так при мезотимпаните деструкция цепи слуховых косточек наблюдается у 10-22% [6, 31, 63, 64],  а холестеатома в барабанной полости – у 11,6-42% пациентов [18, 61, 62, 65, 66]. Учитывая современную тенденцию хирургического лечения любой формы ХГСО, то для планирования объема, этапов операции и функциональных результатов необходимо диагностировать эти изменения"}, "c-class-chol": {"s": "ok", "sec": "1.5", "page": 12, "q": "Самой современной классификацией холестеатомы является недавно представленная Европейской Академией отологов и нейроотологов (EAONO) и японской ассоциацией отологов (JOS) для оценки современных тенденций возникновения, распространения холестеатомы, стандартизации этой патологии и хирургических вмешательств. В ней выделяются 4 типа и 4 стадии в зависимости от ее этиологии и распространения. Среди типов холестеатом выделяется врожденная и три вида приобретенной: ненатянутого (p. flaccidа), натянутого отдела (p. tensa) и вторичная вследствие перфорации натянутого отдела барабанной перепонки. Стадии холестеатомы определяют ее распространение у каждого типа холестеатом: 1 стадия – расположение в одном регионе, 2 – занимает два и более региона, 3 – с экстракраниальным осложнением или патологическим состоянием и 4 – с внутричерепным осложнением. Стадии распространения соответствуют анатомическим областям в среднем ухе: труднодоступные зоны (S:S1 – надтубарный синус, S2 – тимпанальный синус), барабанная полость (Т), аттик (А) и сосцевидный отросток (М), что соответствует общему названию STAM"}, "c-clin": {"s": "ok", "sec": "1.6", "page": 13, "q": "Клиническая картина ХГСО предполагает наличие жалоб на сниженный слух и шум в ухе, а также - перфорации барабанной перепонки различной локализации с выделениями или холестеатомой"}, "c-meso": {"s": "ok", "sec": "1.6", "page": 13, "q": "Мезотимпанит – форма хронического среднего отита с локализацией перфорации в натянутом отделе барабанной перепонки. В настоящее время встречается у 48-69% больных ХГСО. Считается относительно благоприятной формой, поскольку у пациентов нет признаков активной остеодеструкции"}, "c-epi": {"s": "ok", "sec": "1.6", "page": 13, "q": "Эпитимпанит встречается у 15-19% больных ХГСО, характеризуется локализацией перфорации в ненатянутом отделе барабанной перепонки и сопровождается кариозным процессом разной степени выраженности в среднем ухе, что может быть причиной внутрилабиринтных и внутричерепных осложнений. Причиной костной резорбции при данной форме отита в 79-97% случаев является холестеатома, которая является производным инфекционно-воспалительного процесса. Наличие ретракционного кармана считается начальной стадией формирования холестеатомы (предхолестеатома). Ретракционные карманы в 80% случаев являются причиной развития холестеатомы"}, "c-epimeso": {"s": "ok", "sec": "1.6", "page": 13, "q": "При эпимезотимпаните, который выявляется у 17-33% пациентов [49], встречаются признаки обеих вышеобозначенных форм"}, "d-crit": {"s": "ok", "sec": "2", "page": 13, "q": "Критерии установления диагноза основаны на анализе результатов комплексного обследования пациента: 1) жалоб; 2) анамнестических данных; 3) физикального обследования; 4) лабораторных исследований; 5) инструментального обследования"}, "d-hear": {"s": "ok", "sec": "2.1", "page": 14, "q": "Рекомендуется опрашивать пациентов о снижении слуха на одно или оба уха [2, 30, 57, 57, 79, 80, 81]. Уровень убедительности рекомендаций С (уровень достоверности доказательств - 5)"}, "d-hear-c": {"s": "ok", "sec": "2.1", "page": 14, "q": "При ХГСО с или без холестеатомы снижение слуха различной степени выраженности отмечают 93-99% пациентов и чаще – двустороннее [2, 30, 57, 79, 80, 81]. При длительном течении заболевания, когда формируются органические его исходы (ТСК, ТФ и ретракционный карман), снижение слуха становится выраженным"}, "d-otor": {"s": "ok", "sec": "2.1", "page": 14, "q": "Рекомендуется опрашивать пациентов о длительности, частоте и характере выделений из уха [30, 45, 80, 81]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5)"}, "d-otor-c": {"s": "ok", "sec": "2.1", "page": 14, "q": "Оторея является второй по значимости жалобой у 76-100% пациентов с ХГСО. Все без исключения пациенты отмечают хотя бы один эпизод выделений из уха на протяжении жизни. В 20% случаев выделения из больного уха беспокоили в детстве, либо несколько раз за всю историю заболевания. Около 50% пациентов жалуются на появление подобных симптомов 1-2 раза в год на фоне переохлаждения, попадания воды в ухо или перенесенного ОРЗ. Почти 30% пациентов беспокоят частые либо постоянные выделения из уха на протяжении последних нескольких лет. Выделения из уха носят различный характер: от скудных слизистых до гнойных с ихорозным запахом"}, "d-otor-epi": {"s": "ok", "sec": "2.1", "page": 14, "q": "Редкие обострения и выраженное снижение слуха характерно для фиброзирующих исходов ХГСО (ТСК и ТФ) и холестеатомного процесса. Именно эпитимпанит опасен бессимптомным течением. В то время как постоянные выделения из уха свидетельствуют в пользу хронического воспаления слизистой оболочки (мукозит). Для холестеатомы типичными являются гнойные выделения с неприятным запахом [30, 79, 80]. В то же время для эпитимпанита характерно бессимптомное течение длительное время"}, "d-tinn": {"s": "ok", "sec": "2.1", "page": 14, "q": "Рекомендуется опрашивать пациентов о наличии ушного шума в одном или обоих ушах [18, 49, 57, 79, 80, 81]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5)"}, "d-tinn-c": {"s": "ok", "sec": "2.1", "page": 15, "q": "для пациентов ХГСО характерным является периодический или постоянный шум в больном ухе разной частотности 19-48% пациентов, который может быть связан как с наличием, так и без обширного дефекта барабанной перепонки (как правило, низкочастотный шум), а также и поражением внутреннего уха на фоне хронического процесса (высокочастотный шум). Причем интенсивность шума увеличивается с появлением ТСК и ТФ"}, "d-full": {"s": "ok", "sec": "2.1", "page": 15, "q": "Рекомендуется опрашивать пациентов о наличии заложенности, ощущении жидкости и дискомфорта в ухе [49, 57, 79]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5)"}, "d-full-c": {"s": "ok", "sec": "2.1", "page": 15, "q": "данные жалобы характерны больше для ХГСО с сохраненным натянутым отделом барабанной перепонки"}, "d-vert": {"s": "ok", "sec": "2.1", "page": 15, "q": "Рекомендуется опрашивать пациентов о наличии эпизодов головокружения в анамнезе [55, 80, 81, 82, 83]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 4)"}, "d-vert-c": {"s": "ok", "sec": "2.1", "page": 15, "q": "от 10 до 27% больных ХГСО с холестеатомой имели эпизоды системного головокружения или неустойчивости различной степени выраженности, которые беспокоили только во время обострения, либо при минимальной физической нагрузке или наклонах/поворотах головы и позволяют достоверно предполагать ХГСО. В 50% случаев подобные жалобы могут свидетельствовать в пользу наличия фистулы лабиринта вследствие резорбции костной капсулы. Разрушение костной стенки лицевого канала может привести к парезу лицевого нерва"}, "d-head": {"s": "ok", "sec": "2.1", "page": 15, "q": "Рекомендуется опрашивать пациентов о наличии головной боли [55, 67, 79, 46, 80]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5)"}, "d-head-c": {"s": "ok", "sec": "2.1", "page": 15, "q": "головная боль различной (височной, височно-теменной, теменной, параорбитальной) локализации беспокоит пациентов, часто на фоне обострения ХГСО. Боль в ухе и головная боль для неосложненного эпитимпанита не характерны, их наличие обычно указывает на возникшие осложнения"}, "d-oto": {"s": "ok", "sec": "2.2", "page": 16, "q": "Рекомендуется выполнять визуальное исследование при патологии органа слуха, осмотр органа слуха (отоскопию, видеоотоскопию) [45, 49, 82, 84, 85]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5) Комментарии: в диагностике ХГСО определяющим методом является отоскопия и отоэндоскопия"}, "d-oto-c": {"s": "ok", "sec": "2.2", "page": 16, "q": "При данных обследованиях обращают внимание на состояние барабанной перепонки (тонкая, толстая, рубцовая, наличие ТСК очагов), наличие, характер и глубину ретракционных карманов, наличие дефекта, его размер, локализацию, характер краев (эпидермизированные, подвернутые внутрь барабанной полости, спаянные со структурами барабанной полости, омозолелые), состояние слизистой оболочки барабанной полости (явления и степень мукозита, очаги ТСК, ТФ, полипозные изменения, грануляции, эпидермизация барабанной полости), состояние цепи слуховых косточек, если они визуализируются (кариес, лизис фрагментов цепи, их эпидермизация), состояние латеральной стенки аттика, адитуса (если есть признаки их деструкции)"}, "muc1": {"s": "ok", "sec": "2.2", "page": 16, "q": "Мукозит I степени проявляется утолщением слизистой оболочки медиальной стенки барабанной полости при отсутствии свободного отделяемого в ней"}, "muc2": {"s": "ok", "sec": "2.2", "page": 16, "q": "II степени – визуально характеризуется подушкообразным утолщением слизистой оболочки медиальной стенки барабанной полости с большим количеством слизистых желез и наличием скудного количества слизистого отделяемого"}, "muc3": {"s": "ok", "sec": "2.2", "page": 16, "q": "III степени – выраженной полиповидной гиперплазией слизистой оболочки мезогипотимпанума с наличием слизистого отделяемого"}, "d-epi-tip": {"s": "ok", "sec": "2.2", "page": 16, "q": "Применение отоэндоскопии позволяет визуально установить диагноз холестеатомы среднего уха в 61% случаев. Следует обратить внимание, что при эпитимпанитах дефект барабанной перепонки может быть точечным, визуализироваться только при продувании пациента, может быть прикрыт серной коркой, а в ряде случаев временно отсутствовать (например, при стойкой ремиссии ХГСО). Тогда особое внимание нужно уделить состоянию латеральной стенки аттика: есть ли хотя бы минимальная деструкция. Иногда заболевание имитирует рецидивирующий экссудативный средний отит, но при внимательном отоэндоскопическом осмотре наряду с прозрачным экссудатом в барабанной полости визуализируется холестеатомный мешок, который может занимать всю барабанную полость, при этом в области ненатянутого отдела барабанной перепонки имеется небольшой ретракционный карман. При наличии глубоких ретракционных карманов целесообразно использование отоскопов с различным углом обзора (00, 300 и 700) для  диагностики глубины и области их распространения", "note": "Углы обзора эндоскопов в PDF напечатаны как «00, 300 и 700» — знак градуса потерян."}, "d-fist": {"s": "ok", "sec": "2.2", "page": 17, "q": "Для диагностики фистул лабиринта большую помощь оказывает фистульная проба"}, "d-tube": {"s": "ok", "sec": "2.2", "page": 17, "q": "Пациентам ХГСО необходимо определение степени проходимости слуховой трубы с помощью пустого глотка, пробы Тойнби, маневра Вальсальвы или продувания слуховой трубы баллоном Политцера. С увеличением степени мукозита отмечается прогрессивное ухудшение вентиляционной и дренажной функции слуховой трубы. Диагностированная дисфункция слуховой трубы может быть причиной существующей ретракции барабанной перепонки, как на этапе обследования, так и в отдаленном послеоперационном периоде. Этот момент необходимо учитывать при проведении хирургического лечения, а также при назначении лечебных и реабилитационных мероприятий в раннем и позднем послеоперационном периодах. Отсутствие проблем со слуховой трубой при ХССО должно насторожить на возможность спонтанной отоликвореи"}, "d-nose": {"s": "ok", "sec": "2.2", "page": 17, "q": "Безусловно, оценка состояния полости носа, околоносовых пазух носа и носоглотки играет немаловажную роль в лечении ХГСО. Искривление перегородки носа, гипертрофический ринит, хроническая патология околоносовых пазух и носоглотки являются причиной нарушения функции слуховых труб и влияют на эффективность лечения"}, "d-fork": {"s": "ok", "sec": "2.4", "page": 18, "q": "Рекомендуется выполнять исследование органа слуха с помощью камертонов при подозрении на снижение слуха [49, 82].  Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5)"}, "d-fork-c": {"s": "ok", "sec": "2.4", "page": 19, "q": "Комментарии: количественные (С128-2048) и качественные камертональные (С128-512) тесты Ринне, Федериче, Вебера являются скринингом определения вида тугоухости - кондуктивного или сенсоневрального и хуже слышащего уха [49, 82] на основании построения слухового паспорта, и показанием для проведения тональной пороговой аудиометрии"}, "d-pta": {"s": "ok", "sec": "2.4", "page": 19, "q": "Рекомендуется выполнять тональную пороговую аудиометрию (ТПА) при диагностике ХГСО [2,30,45,49, 57, 77, 83,88]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 4)"}, "d-pta-c": {"s": "ok", "sec": "2.4", "page": 19, "q": "аудиологическое обследование пациентов с ХГСО позволяет определить вид тугоухости и прогнозировать функциональный результат операции. ТПА точно определяет степень и характер тугоухости (кондуктивная, смешанная и нейросенсорная) и возможности ее реабилитации. Несмотря на то, что данное исследование является субъективным, оно позволяет прогнозировать результат операции, контролировать его динамику в отдаленном послеоперационном периоде. Так у пациентов с порогами КП выше 30 дБ в диапазоне разговорных частот даже при идеально проведенной хирургической операции качественного улучшения слуха нельзя ожидать. Идеальным вариантом оценки динамики результата является проведение ТПА на одном и том же аппарате и одним и тем же исследователем"}, "d-pta-type": {"s": "ok", "sec": "2.4", "page": 19, "q": "Для пациентов с ХГСО характерны кондуктивная и смешанная тугоухость различной степени выраженности, которая зависит от дефекта барабанной перепонки, целостности слуховой цепи, ее подвижности и токсического влияния продуктов воспаления на структуры внутреннего уха. Глухота у пациентов с ХГСО часто связана с фистулой лабиринта вследствие деструкции кости холестеатомным процессом"}, "d-pta-kvi": {"s": "ok", "sec": "2.4", "page": 19, "q": "Однако ТПА не дает возможности выявить характерные для холестеатомы изменения в среднем ухе, так как КВИ не коррелирует с вариантами деструкции цепи слуховых косточек. Холестеатома и грануляционная ткань в полости среднего уха могут передавать акустическую энергию к структурам внутреннего уха"}, "d-xray": {"s": "ok", "sec": "2.4", "page": 20, "q": "Рекомендуется рентгенография височных костей в укладках по Шуллеру и Майеру у пациентов с ХГСО без холестеатомы для оценки состояния сосцевидного отростка [2, 60, 150]. Уровень убедительности рекомендаций C (уровень достоверности доказательств – 5)"}, "d-xray-c": {"s": "ok", "sec": "2.4", "page": 20, "q": "возможно проведение обследования у пациентов с ХГСО при отсутствии подозрения на холестеатому и осложненного течения заболевания"}, "d-ct": {"s": "ok", "sec": "2.4", "page": 20, "q": "Рекомендуется проведение компьютерной томографии (КТ) височных костей у пациентов ХГСО для оценки состояния структур височной кости [9, 30, 60, 78, 82, 93, 94, 95, 96; 97, 98]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 4)"}, "d-ct-c": {"s": "ok", "sec": "2.4", "page": 20, "q": "КТ височных костей является методом первичной диагностики и позволяет прижизненно и неинвазивно получить информацию о патологии этой локализации: определить характер, распространенность процесса, анатомические особенности (низкое стояние дна средней черепной ямки, высокое стояние луковицы яремной вены, предлежание сигмовидного синуса, дегисценции канала лицевого нерва, строение сосцевидного отростка, наличие перегородки Корнера, дегисценции лабиринта), состояние стенок барабанной полости и антро-мастоидального отдела (наличие и размер деструкции), цепи слуховых косточек, слизистой оболочки, узких пространств барабанной полости (синусы и карманы), характер патологического субстрата в полостях среднего уха. Исследование проводится в аксиальной и коронарной (фронтальной) проекциях, с МПР (так называемая виртуальная эндоскопия) и рентгеноденситометрией. Идеальная толщина среза 0,5-0,8 мм"}, "d-ct-acc": {"s": "ok", "sec": "2.4", "page": 20, "q": "С помощью КТ височных костей диагностируются признаки ХГСО в 99% случаев, деструкцию костных стенок среднего уха в 55-97% [83, 93,95, 97]. Определить характер патологического субстрата (холестеатома, фиброз, грануляции, экссудат, гной) не представляется возможным, так как плотность холестеатомы и мягкотканного субстрата идентична – от +30 до +40 ед. НU. Однако заподозрить наличие холестеатомы в 88% случаев позволяют локализация образования, деструктивные изменения стенок барабанной полости, цепи слуховых косточек, антромастоидальной области, расширение входа в антрум, увеличение его размеров, разрушение латеральной стенки аттика и/или адитуса, дефект задней стенки наружного слухового прохода, разрушение стенок канала лицевого нерва на протяжении и наличие фистул лабиринта  (чаще горизонтального, реже вертикального и заднего полукружных каналов)"}, "d-ct-nochol": {"s": "ok", "sec": "2.4", "page": 21, "q": "Для ХГСО без холестеатомы по КТ височных костей характерны изменения слизистой оболочки в барабанной полости, рубцовый процесс вокруг цепи слуховых косточек, возможен дефект цепи слуховых косточек, чаще за счет лизиса длинной ножки наковальни, реже за счет лизиса суперструктур стремени, тела наковальни и головки молотка. Антрум при мезотимпаните в стадии ремиссии обычно пневматизирован. Как правило, сосцевидный отросток при ХГСО компактный, склеротический"}, "d-ct-postop": {"s": "ok", "sec": "2.4", "page": 21, "q": "КТ височных костей малоинформативно при оценке состояния послеоперационного уха, поскольку рубцовая ткань, грануляции, пластический аутоматериал имеют одинаковую плотность с холестеатомой. Подозревать холестеатому можно только при оценке результатов в динамике (рост «подозрительного» образования)"}, "d-ct-time": {"s": "ok", "sec": "2.4", "page": 21, "q": "Для объективной верификации распространенности процесса КТ височных костей необходимо выполнять не ранее чем через 3-6 месяцев после обострения заболевания. Выполнение этого исследования в период обострения необоснованно расширяет объем хирургического вмешательства и оправдано только при осложненном течении заболевания"}, "d-mri": {"s": "ok", "sec": "2.4", "page": 22, "q": "Рекомендуется проведение МРТ височных костей (костной ткани, одна область) пациентам с ХГСО с подозрением на холестеатому или ее рецидив [7, 9, 95, 96, 103, 104]. Уровень убедительности рекомендаций А (уровень достоверности доказательств – 2)"}, "d-mri-c": {"s": "ok", "sec": "2.4", "page": 22, "q": "Комментарии: МРТ в определенных режимах (T1, T2, EPI DWI, non-EPI DWI) является методом достоверной диагностики холестеатомы и ее рецидива после операции. Метод обладает чувствительностью для холестеатомы в 77-100%, специфичностью – в 86-100% случаев и позволяет отличить ее от других мягкотканных образований височной кости: секрета, грануляций и холестероловой гранулемы. В пользу холестеатомы будет свидетельствовать низкоинтенсивный сигнал в Т1, гипер- или среднеинтенсивный сигнал в режиме Т2 и non-EPI DWI [7, 9,95,103, 105, 106, 107, 107, 108]. При этом отмечается, что на чувствительность и специфичность метода влияет размер холестеатомы (2-3 мм или <5 мм), что выполнение МРТ для диагностики рецидива холестеатомы экономически выгодней, чем ревизионная хирургия, и является альтернативой хирургии"}, "d-mri-ct": {"s": "ok", "sec": "2.4", "page": 22, "q": "Некоторые авторы для определения холестеатомы и ее локализации рекомендуют комбинацию КТ-МРТ исследований или их совмещение, которые повышают эффективность диагностики холестеатомы: чувствительность – 96%, специфичность – 100%"}, "d-vest": {"s": "ok", "sec": "2.4", "page": 22, "q": "Рекомендуется вестибулометрия пациентам с ХГСО и холестеатомой, осложненной фистулой лабиринта [83]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 4)"}, "d-vest-c": {"s": "ok", "sec": "2.4", "page": 22, "q": "у пациентов с ХГСО с жалобами на головокружение системного характера и неустойчивость, признаками фистулы лабиринта показано проведение вестибулометрии для оценки состояния вестибулярного анализатора больного уха и диагностики осложнения. Диагностика фистулы лабиринта на дооперационном этапе предупреждает послеоперационные кохлеовестибулярные расстройства"}, "d-lab": {"s": "ok", "sec": "2.3", "page": 17, "q": "Лабораторные методы исследования выполняются при подготовке к плановой госпитализации (плановое хирургическое лечение)"}, "d-cult": {"s": "ok", "sec": "2.3", "page": 17, "q": "Рекомендуется проводить микробиологическое (культуральное) исследование гнойного отделяемого на аэробные и факультативно-анаэробные микроорганизмы,  определение чувствительности микроорганизмов к антимикробным химиотерапевтическим препаратам [3, 45, 49, 60, 88]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5)"}, "d-cult-c": {"s": "ok", "sec": "2.3", "page": 18, "q": "во всех случаях ХГСО для выбора адекватной этиотропной терапии необходимо проводить бактериологическое исследование с определением возбудителя и его чувствительности к антибактериальным препаратам системного действия"}, "d-fung": {"s": "ok", "sec": "2.3", "page": 18, "q": "Рекомендуется Микробиологическое (культуральное) исследование отделяемого из ушей на дрожжевые грибы, Микробиологическое (культуральное) исследование отделяемого из ушей на мицелиальные грибы. [3, 150, 151]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5) Комментарии: микологическое исследование выполняется только при подозрении на грибковый характер процесса"}, "d-histo": {"s": "ok", "sec": "2.3", "page": 18, "q": "Рекомендуется проводить цитологическое исследование микропрепарата тканей уха, патолого-анатомическое исследование биопсийного (операционного) материала тканей уха [2, 3, 89, 90]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 4)"}, "d-histo-c": {"s": "ok", "sec": "2.3", "page": 18, "q": "патолого-анатомическое исследование выполняется во всех случаях удаления патологической ткани для определения характера воспаления. При наличии атипичного воспалительного процесса спектр лабораторных исследований расширяется для диагностики этиологии процесса (туберкулез, гранулематоз Вегенера). При отсутствии положительных результатов диагностики и неэффективности стандартного лечения их повторяют через 3 месяца"}, "d-cons": {"s": "ok", "sec": "2.5", "page": 22, "q": "Рекомендуются консультации врача-невролога, врача-нейрохирурга, врача- терапевта [3, 49, 60, 89] при сопутствующей соматической патологии и подозрении на осложненное течение заболевания.  Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5)"}, "d-cons-c": {"s": "ok", "sec": "2.5", "page": 23, "q": "при атипичном течении воспаления и осложнениях ХГСО требуются дополнительные исследования, а также консультации невролога, нейрохирурга, фтизиатра, терапевта и ревматолога"}, "t-goal": {"s": "ok", "sec": "3", "page": 23, "q": "Целью лечения пациентов с ХГСО является санация структур среднего уха для достижения стойкой ремиссии заболевания, профилактики осложнений и тугоухости"}, "t-cons": {"s": "ok", "sec": "3.1", "page": 23, "q": "Рекомендуется проведение консервативной терапии при обострении ХГСО и как подготовка к операции при неосложненном течении заболевания [2, 57, 60, 82]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5)"}, "t-cons-c": {"s": "ok", "sec": "3.1", "page": 23, "q": "консервативная терапия у пациентов с ХГСО проводится при обострении, для достижения ремиссии хронического процесса (как подготовка к хирургическому вмешательству), в раннем послеоперационном периоде (после проведения санирующего вмешательства) и включает в себя назначение бета-лактамных антибиотиков (J01C Бета-лактамные антибактериальные препараты: пенициллины и J01D Другие бета-лактамные антибактериальные препараты), анальгетиков, кортикостероидов (S01BA) и процедур, направленных на улучшение функций слуховой трубы"}, "t-cons-where": {"s": "ok", "sec": "3.1", "page": 23, "q": "Проводится амбулаторно при неосложненном и в стационаре – при осложненном течении заболевания. В качестве основного вида лечения консервативная терапия, носящая паллиативный характер, оправдана только у пациентов с тяжелыми сопутствующими заболеваниями при условии регулярного наблюдения"}, "t-dry": {"s": "ok", "sec": "3.1", "page": 23, "q": "Не рекомендуется проводить какое-либо лечение при сухом перфоративном среднем отите"}, "cw-dry": {"s": "ok", "sec": "3.2", "page": 28, "q": "При наличии перфорации барабанной перепонки и отсутствии возможностей улучшения слуха тимпанопластику необходимо выполнять для предупреждения рецидивирования ХГСО", "note": "Противоречит фразе раздела 3.1 «Не рекомендуется проводить какое-либо лечение при сухом перфоративном среднем отите»."}, "t-abx": {"s": "ok", "sec": "3.1", "page": 23, "q": "Антибактериальная терапия проводится с учетом флоры, ее чувствительности к препаратам и возможности проникновения через гематоэнцефалический барьер. Препаратами выбора являются бета-лактамных антибиотики (J01C Бета-лактамные антибактериальные препараты: пенициллины и J01D Другие бета-лактамные  антибактериальные препараты), в некоторых случаях - респираторные фторхинолоны"}, "t-abx-sys": {"s": "ok", "sec": "3.1", "page": 24, "q": "Препараты общего действия назначают, как правило, при выраженном обострении ХГСО, а также при тяжелых и распространенных деструктивных формах ХГСО. При необходимости хирургического лечения назначение периоперационной антибактериальной профилактики должно соответствовать характеру и объему оперативного вмешательства"}, "t-abx-mix": {"s": "ok", "sec": "3.1", "page": 24, "q": "В случае смешанной флоры приветствуются комбинации 2-3 препаратов для перекрестного воздействия сразу на все виды патогенных микроорганизмов. Например, цефалоспорины (J01D: Другие бета-лактамные антибактериальные препараты) и фторхинолоны(код АТХ J01MA). Возможна комбинация противомикробных препаратов (код АТХ S02AA) с антибиотиками для наружного применения (код АТХ D01A Противогрибковые препараты для местного применения) и противогрибковыми препаратами для наружного применения"}, "t-local": {"s": "ok", "sec": "3.1", "page": 24, "q": "Ключевая роль все же принадлежит антисептикам и дезинфицирующим средствам (D08A), топическим антибактериальным препаратам (S02AA Противомикробные препарат), D01AE (Другие противогрибковые препараты для местного применения) противогрибковым препаратам для местного применения и глюкокортикостероидам (S02CA Кортикостероиды в комбинации с противомикробными средствами). Топические фторхинолоны являются наиболее эффективными средствами лечения ХГСО с минимальными побочными эффектами: они воздействуют на основную патогенную флору (75,6% изолятов чувствительны к данной группе препаратов) и не являются ототоксичными, поэтому можно использовать у пациентов с перфорацией барабанной перепонки. Местное лечение эффективно только после тщательного удаления патологического содержимого из среднего уха с помощью аспирации или ирригации"}, "t-gran": {"s": "ok", "sec": "3.1", "page": 24, "q": "Пациентам с наличием грануляций в барабанной полости необходимо их удалять (если это возможно), либо проводить химическую каустику: соединениями серебра (D08AL). Грануляции хорошо регрессируют при назначении топических кортикостероидов"}, "t-steroid": {"s": "ok", "sec": "3.1", "page": 24, "q": "Назначение кортикостероидов в виде капель или комбинированных препаратов целесообразно при наличии вялотекущего воспаления слизистой оболочки (мукозите). При отсутствии эффекта от местной терапии в течение 1-3 месяцев, что характерно для мукозита барабанной полости, проводится операция с использованием дренирующих методик"}, "t-boric": {"s": "ok", "sec": "3.1", "page": 25, "q": "При холестеатомном процессе для местной терапии эффективными являются противомикробные препараты (Борная кислота и препараты на ее основе) (S02AA03), которые помимо антисептического обладают и дегидратационным эффектом, что значительно снижает воспалительные явления, за счет дегидратации"}, "t-fung": {"s": "ok", "sec": "3.1", "page": 25, "q": "Пациентам с грибковой флорой противопоказано назначение противомикробных препаратов и кортикостероидов в форме капель. Таких пациентов необходимо вести строго согласно существующим алгоритмам применения противогрибковых препаратов для местного применения (D01A). Лечение таких пациентов часто длительное и требует привлечения смежных специалистов (микологов)"}, "cw-fung": {"s": "ok", "sec": "3.1", "page": 24, "q": "Возможна комбинация противомикробных препаратов (код АТХ S02AA) с антибиотиками для наружного применения (код АТХ D01A Противогрибковые препараты для местного применения) и противогрибковыми препаратами для наружного применения", "note": "Противоречит фразе «Пациентам с грибковой флорой противопоказано назначение противомикробных препаратов и кортикостероидов в форме капель»."}, "t-tube": {"s": "ok", "sec": "3.1", "page": 25, "q": "Для лечения дисфункции слуховой трубы следует придерживаться определенного алгоритма: 1) устранение патологии полости носа и носоглотки, начиная с использования деконгестантов и других назальных препаратов для местного применения (R01A) и топических назальных кортикостероидов и заканчивая хирургическим лечением; 2) улучшение проходимости слуховой трубы с помощью продувания слуховых труб баллоном Политцера, курса катетеризаций слуховой трубы с транстубарным введением различных препаратов; 3) улучшение функционирования слуховой трубы за счет налаживания механизмов самопроизвольного открытия и закрытия ее просвета с помощью назначения специальной гимнастики или проведения курса электрической стимуляции мышц слуховой трубы"}, "t-surg": {"s": "ok", "sec": "3.2", "page": 25, "q": "Основной вид лечения пациентов с ХГСО – хирургический, который проводится с учетом патогенеза и особенностей клинической картины. Только с помощью оперативного пособия возможно не только полностью санировать больное ухо, но и улучшить качество жизни пациента. Поэтому на современном этапе любой пациент, страдающий ХГСО, является потенциальным кандидатом на оперативное лечение [49, 82]. Операции при ХГСО необходимо проводить в период ремиссии заболевания (не ранее чем через 3-6 месяцев после последнего обострения) для уменьшения объема операции, лучшей дифференцировке жизнеспособных элементов среднего уха, для снижения частоты осложнений и повышения ее эффективности"}, "t-surg-urg": {"s": "ok", "sec": "3.2", "page": 25, "q": "Вынужденное оперативное вмешательство в период обострения или осложнений предусматривает только санацию среднего уха открытому типу (в случаях внутричерепных осложнений – расширенная), выполнение которого технически сложно из-за плохой визуализации структур на фоне кровотечения, что повышает риск возникновения ятрогенных осложнений. В связи с этим рекомендуется выполнять санирующие операции пациентам с ХГСО с осложнениями в отделениях ургентной направленности, а вне обострения – в  специализированных отделениях или Центрах, имеющих соответствующее оборудование и специалистов, владеющих методами реконструктивной хирургии среднего уха. Принцип ранней хирургии ХГСО на «сухом ухе» позволяет лучше санировать очаг воспаления, сохранить слуховую функцию, исходную анатомию среднего уха, сократить сроки реабилитации"}, "t-drain": {"s": "ok", "sec": "3.2", "page": 26, "q": "Рекомендуются дренирующие операции у пациентов с ХГСО и мукозитом 2 и 3 стадией [2, 7, 57, 77]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5)"}, "t-drain-c": {"s": "ok", "sec": "3.2", "page": 26, "q": "выбор методики операции у пациентов с ХГСО индивидуален, зависит от формы ХГСО и его последствий, степени распространенности и выраженности патологического процесса, анатомических особенностей строения височной кости, степени слуховых нарушений, состояния слуховой трубы, наличия осложнений, от квалификации и опыта хирурга"}, "t-tp": {"s": "ok", "sec": "3.2", "page": 26, "q": "Рекомендуется тимпанопластика пациентам с ХГСО для санации среднего уха и улучшения слуха [7, 30, 45, 61, 67, 68, 82, 87, 112, 117]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5)"}, "t-tp-c": {"s": "ok", "sec": "3.2", "page": 26, "q": "в настоящее время при мезотимпаните проводятся тимпанопластики различного типа (по Х. Вульштейну – 4, по М. Тосу – 5 и мирингопластика) в зависимости от степени разрушения цепи слуховых косточек с использованием различных протезов (аутопротезы из хряща и наковальни, кортикальной кости, титановые протезы, и др.) и аутоматериалов для пластики барабанной перепонки [118, 119]. Тимпанопластика выполняется трансмеатальным доступом интрамеатальным, эндауральным или заушным подходом, под местной анестезией или наркозом, под контролем эндоскопов или микроскопа, первым или вторым этапом, с различными способами укладки трансплантатов в зависимости от предпочтений хирурга"}, "t-tp-cond": {"s": "ok", "sec": "3.2", "page": 26, "q": "На выбор хирургического подхода влияет локализация перфорации и анатомия наружного слухового прохода. Анатомо-функциональная эффективность операции во многом зависит от времени, прошедшего с момента последнего обострения, полиморфизма изменений в среднем ухе, локализации и размера дефекта, состояния функций слуховой трубы и слизистой оболочки, способа реконструкции, опыта хирурга и качества послеоперационного периода. Обязательным условием успешной тимпанопластики является отсутствие выделений минимум 3-6 месяцев"}, "t-tp-eff": {"s": "ok", "sec": "3.2", "page": 27, "q": "В настоящее время эффективность тимпанопластики составляет 43-98% [7,14, 18, 87, 126, 127, 128]. Вероятность осложнения в виде глухоты оперированного уха оценивают в 1-2%. Лучшие результаты тимпанопластики (у 93,3%) наблюдаются при сухих перфорациях независимо от техники (underlay или overlay) укладки трансплантатов"}, "t-mastoid": {"s": "ok", "sec": "3.2", "page": 27, "q": "До сих пор имеются разные мнения по поводу объема операции для тимпанопластики у пациентов с ХГСО без холестеатомы. В то же время многими исследованиями доказано, что мастоидотомия при тимпанопластике не дает лучшего анатомо-морфологического результата (реперфорация при тимпанопластике у 24%, при сочетании с мастоидотомией – у 17-22%), не улучшает аэрацию структур среднего уха по данным КТ височных костей (при тимпанопластике аэрация клеток сосцевидного отростка восстанавливается – у 43%, тогда как с мастостоидотомией – у 50%), но увеличивает объем и риск операции [9, 68, 100]. Мастоидотомия при тимпанопластике считается обязательной в случаях вялотекущих форм ХПСО без холестеатомы и отсутствии эффекта от системной и местной антибиотикотерапии"}, "t-endo": {"s": "ok", "sec": "3.2", "page": 27, "q": "Использование эндоскопа в качестве дополнения к микроскопу улучшает визуализацию структур барабанной полости. Преимущества использования только эндоскопов в хирургии ХГСО перед микроскопом по данным системного обзора не доказаны"}, "t-graft": {"s": "ok", "sec": "3.2", "page": 27, "q": "Большинство специалистов при тотальных и субтотальных дефектах барабанной перепонки с изменением слизистой оболочки барабанной полости оптимальными трансплантатами для тимпанопластики считают комбинацию аутофасции, аутохряща и кожных трансплантатов для профилактики реперфорации.  Использование тонких аутохрящевых пластин препятствует ретракции и западению созданной конструкции и не влияет на ее акустические свойства"}, "t-muc": {"s": "ok", "sec": "3.2", "page": 28, "q": "В пользу тимпанопластики при мукозите свидетельствуют многочисленные факты послеоперационной трансформации толстой инфильтрированной слизистой оболочки в тонкий нормально выглядящий и функционирующий эпителий после улучшения функций слуховой трубы, восстановления аэрации и внутреннего дренирования. В зависимости от выраженности мукозита выполняют мукозэктомию инструментально или лазером. Удачные исходы тимпанопластики при выраженном мукозите отмечены в случаях, когда тимпанопластику выполняли с введением в барабанную полость дренажной трубки под меатальный лоскут или с вскрытием антрума (раздельная аттикоантротомия) и дренированием через него барабанной полости в послеоперационном периоде до 2 недель"}, "t-stage": {"s": "ok", "sec": "3.2", "page": 28, "q": "При необходимости выполнения тимпанопластики вторым этапом следует ее проводить через 8-12 месяцев. При наличии перфорации барабанной перепонки и отсутствии возможностей улучшения слуха тимпанопластику необходимо выполнять для предупреждения рецидивирования ХГСО"}, "t-ossi": {"s": "ok", "sec": "3.2", "page": 28, "q": "При анализе результатов использования искусственных и аутопротезов при оссикулопластике не отмечено функциональных различий. В то же время при неиспользовании аутохрящевого прикрытия искусственного протеза в 6 раз увеличивается его смещение"}, "t-san": {"s": "ok", "sec": "3.2", "page": 29, "q": "Рекомендуются санирующие операции у пациентов с ХГСО с холестеатомой [7, 29, 33, 45, 49, 59, 67, 69, 72, 78, 81, 83, 86, 105]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 4)"}, "t-san-c": {"s": "ok", "sec": "3.2", "page": 29, "q": "главным принципом хирургии холестеатомы является полное ее удаление и профилактика факторов рецидивирования"}, "t-san-how": {"s": "ok", "sec": "3.2", "page": 29, "q": "При эпитимпаните, эпимезотимпаните с холестеатомой проводятся в зависимости от распространенности процесса «открытые», «полуоткрытые» и «закрытые» варианты санирующих операций с тимпанопластикой или без, для которых используются интрамеатальный, эндауральный или заушный хирургические подходы трансмеатальным или трансмастоидальным доступом [6, 7, 60, 72, 81]. Санирующие операции из-за большого их объема и длительности необходимо выполнять под общей анестезией"}, "t-san-attic": {"s": "ok", "sec": "3.2", "page": 30, "q": "При локализованных холестеатомных процессах (аттик или аттик-адитус) возможно проведение минимальных по объему операций (аттикотомия трансмеатальным доступом). При этом обязательным условием является тщательное удаление процесса из синусов и карманов среднего уха для достижения полной санации"}, "t-oc": {"s": "ok", "sec": "3.2", "page": 30, "q": "До сих пор не стихают споры по поводу того, какую хирургическую технику использовать при ХГСО с холестеатомой: «открытую» (удаление задней стенки слухового прохода) или «закрытую» (оставлять ее или реконструировать). При первом варианте вы избавляете пациента от необходимости повторных хирургических вмешательств, но не от регулярных визитов к оториноларингологу, поскольку сформированная антромастоидальная полость требует наблюдения и ухода. При втором – обязательна ревизия полостей среднего уха через 8-12 месяцев или МРТ для исключения рецидива холестеатомы [7,82, 99, 136, 139]. Однако, необходимо учитывать не только клиническую картину и предпочтения хирурга, но и интересы пациента: его ожидания от хирургического лечения, настрой на повторное хирургическое вмешательство и доступность квалифицированной помощи в амбулаторнополиклиническом учреждении по месту жительства. Безусловно, санирующие операции «закрытого» типа опаснее внутричерепными осложнениями, чем «открытые», поэтому выбор варианта операции определяется характером, локализацией процесса и опытом хирурга при постоянном динамическом его наблюдении. При отсутствии возможности постоянного наблюдения в послеоперационном периоде предпочтительней является «открытая» методика санирующей операции"}, "t-oc-ind": {"s": "ok", "sec": "3.2", "page": 30, "q": "«Закрытые» методики (аттико-адитотомия, аттико-антротомия (ретроградная мастоидотомия) и раздельная антромастоидотомия) предпочтительны при ограниченных холестеатомных процессах, «открытые» (модифицированная радикальная мастоидэктомия (сanal-wall-down (CWD) procedures), консервативнорадикальная, общеполостная санирующая операция, антромастоидотомия с удалением задней стенки слухового прохода и радикальная мастоидэктомия) – при распространенных деструктивных процессах, а также у пациентов с признаками активной холестеатомы или вялотекущего обострения"}, "t-hybrid": {"s": "ok", "sec": "3.2", "page": 31, "q": "Современной тенденцией в последнее время является сочетание «открытой» и «закрытой» методик («полуоткрытый» вариант, гибридная техника), то есть выполнение аттикоантро/мастоидотомии с эпитимпанопластикой облитерацией антрального/мастоидального отделов аутокостью, аутохрящем, мышечно-фасциальным лоскутом, мышечным лоскутом на ножке или другим инертным синтетическим материалом гидроксиапатит, биокерамика, биостекло) и тимпанопластикой. В результате чего сохраняется анатомическая структура среднего и наружного уха, близкая к исходной, улучшается качество жизни пациента, поскольку нет риска развития болезни послеоперационной полости и, следовательно, необходимости пожизненного наблюдения врача-оториноларингологом"}, "t-recur": {"s": "ok", "sec": "3.2", "page": 32, "q": "При обнаружении рецидива холестеатомы после «закрытой» санирующей операции рекомендуется расширять объем операции до антромастоидотомии с удалением задней стенки и формированием открытой полости"}, "t-postop": {"s": "ok", "sec": "3.2", "page": 32, "q": "Несомненно, грамотное ведение послеоперационного периода также влияет на результаты санации и реконструкции. Многие специалисты отмечали улучшение морфофункциональной эффективности операции после комплексного послеоперационного лечения пациентов с ХГСО, включающего адекватную длительность тампонады наружного слухового прохода с комбинированными противомикробными (S02AA Противомикробные препараты; D, S) препаратами (после тимпанопластики – 10-14 дней, после санирующей операции – 14-21), местное лекарственное и физиотерапевтическое воздействия на слуховую трубу и слизистую оболочку среднего уха. Важным факторов эффективности лечения является и квалифицированное наблюдение в отдаленном периоде после операции"}, "r-aid": {"s": "ok", "sec": "4", "page": 32, "q": "Рекомендуется проведение электроакустической реабилитации у пациентов с ХГСО при асоциальном слухе (тугоухость > II степени) и отсутствии возможности его улучшения [6, 115]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5)"}, "r-aid-c": {"s": "ok", "sec": "4", "page": 33, "q": "при высоких порогах слуха по КП выше 30 дБ на оба уха показано слухопротезирование, в том числе и после операции в отдаленном периоде наблюдения"}, "p-obs": {"s": "ok", "sec": "5", "page": 33, "q": "Рекомендуется наблюдение пациентов с ХГСО, которым противопоказано проведение хирургического лечения, либо по каким-то причинам оно отсрочено, а также пациентов, отказывающихся от хирургического вмешательства. Данная категория пациентов должна наблюдаться квалифицированным специалистом амбулаторно-поликлинического звена с частотой 1 раз в 6 месяцев и при обострении ХГСО получать консервативное лечение для купирования местного воспаления [152]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5)"}, "p-postop": {"s": "ok", "sec": "5", "page": 33, "q": "Рекомендуется после тимпанопластики и санирующих операций наблюдение с частотой посещения 1 раз в год врачом амбулаторно-поликлинического звена и отохирургом учреждения, где была проведена операция минимум до 5 лет с момента операции. Цель наблюдения – выявление рецидивов перфорации, холестеатомы и тугоухости [152]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5)"}, "p-prev": {"s": "ok", "sec": "5", "page": 33, "q": "Рекомендуется для профилактики обострений у пациентов с ХГСО санация полости носа и носоглотки, осведомленность о характере своего заболевания, адекватное отношение к своему здоровью, уход за больным ухом (беречь ухо от воды, проводить профилактику возможных обострений на фоне ОРЗ) и своевременное обращение к врачу амбулаторно-поликлинического звена и специалисту учреждения, где была проведена операция [152]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5)"}, "x-post": {"s": "ok", "sec": "7", "page": 34, "q": "После операции в зависимости от ее методики рекомендуется постельный режим с положением на противоположном ухе. Пациенты с ХГСО должны быть осведомленным о характере своего заболевания, о ключевых моментах ухода за больным ухом (беречь ухо от воды, проводить профилактику возможных обострений на фоне ОРЗ). После операции необходимо 1 месяц избегать физических нагрузок, 3 месяца – авиаперелетов, ухо беречь от воды до момента завершения реабилитационного периода"}, "h-who": {"s": "ok", "sec": "6", "page": 33, "q": "Первичный осмотр (прием) врача-оториноларинголога. Первичный осмотр (прием) врача-сурдолога-оториноларинголога"}, "h-emerg": {"s": "ok", "sec": "6", "page": 33, "q": "Медицинские показания для госпитализации: 1. Экстренная госпитализация:   при обострении ХГСО с экстра- и интракраниальными осложнениями"}, "h-plan": {"s": "ok", "sec": "6", "page": 34, "q": "Плановая госпитализация:  при ХГСО (в том числе с холестеатомой) в стадии вялотекущего воспаления или ремиссии (не менее 3-6 месяцев) для проведения хирургического лечения. Показаниями к плановой госпитализации для хирургического лечения являются:  жалобы на снижение слуха и субъективный ушной шум у пациентов с ХГСО;  жалобы на снижение слуха и скудные выделения из уха у пациентов с ХГСО, не купирующиеся консервативной терапией;  наличие клинических проявлений ХГСО независимо от вида тугоухости;  отсутствие общих противопоказаний для проведения планового хирургического вмешательства;  наличие необходимых обследований для проведения операций, установленных стационаром"}, "h-disch": {"s": "ok", "sec": "6", "page": 34, "q": "Показания к выписке пациента из стационара:  при экстренной госпитализации – отсутствие угрозы жизни пациенту и восстановление его нормальной жизнедеятельности;  при плановой – в зависимости от объема операции и общего самочувствия пациента. Выписка проводится на 3-5 день после окончания противовоспалительной и симптоматической терапии с тампонами в наружном слуховом проходе, которые удаляются через 2-3 недели в зависимости от вида и объема операции в амбулаторных условиях. Оценка слуховой функции с помощью ТПА проводится через 3 и 12 месяцев в амбулаторных условиях"}, "x-eval": {"s": "ok", "sec": "Прил. А3", "page": 52, "q": "Оценочными инструментами эффективности лечения являются наличие жалоб больных на снижение слуха и оторею, которые свидетельствуют об эффективности санации среднего уха; отоэндоскопия – указывающая на наличие анатомического результата (закрытие перфорации барабанной перепонки, отсутствие отореи, эпидермизацию в созданной послеоперационной полости); данные тональной пороговой аудиометрии – свидетельствующие о функциональном результате лечения или необходимости или возможности проведения реконструкции структур среднего уха при тугоухости I-III степени; данные КТ височных костей или МРТ – указывающие на санацию структур среднего уха или наличие воспалительной деструкции височной кости и холестеатомы; данные вестибулометрии – свидетельствующие о вестибулярной функции при фистулах лабиринта у больных ХГСО"}, "x-compl": {"s": "ok", "sec": "Прил. В", "page": 54, "q": "заболевания, связанные с хроническим воспалительным процессом в среднем ухе, ведущие к прогрессирующему снижению слуха, экстра- и интракраниальным осложнениям (лабиринтиту, периферическому парезу лицевого нерва, менингиту, абсцессу головного мозга и тромбозу сигмовидного синуса"}}, "terms": {}};
